fn poll_acp_startup(&mut self, context: &egui::Context) {
    let Some(startup) = self.acp_startup.as_ref() else {
        return;
    };
    if let Some(progress) = startup.task.latest_progress() {
        self.status = Some(progress);
    }
    let Some(result) = startup.task.poll() else {
        context.request_repaint_after(std::time::Duration::from_millis(50));
        return;
    };
    let Some(startup) = self.acp_startup.take() else {
        return;
    };
    match result {
        Err(error) => match startup.target {
            AcpStartupTarget::Ask {
                gameengine_session_id,
                ..
            } => {
                let diagnostic = format!("ACP Ask startup failed: {error}");
                self.status = Some(diagnostic.clone());
                let _ = self.host.append_message(
                    &gameengine_session_id,
                    ConversationRole::System,
                    diagnostic,
                );
            }
            AcpStartupTarget::Build { run_id, .. } => {
                self.fail_run(&run_id, format!("ACP Build startup failed: {error}"));
            }
        },
        Ok(started) => match startup.target {
            AcpStartupTarget::Ask {
                gameengine_session_id,
                prompt,
            } => {
                if self.selected_session != gameengine_session_id {
                    let mut session = started.session;
                    let _ = session.cancel();
                    let _ = session.close();
                    return;
                }
                let acp_session_id = match self.acp.attach_started_ask_session(
                    &self.host,
                    &startup.agent_id,
                    started.runtime,
                    started.session,
                    &gameengine_session_id,
                ) {
                    Ok(session_id) => session_id,
                    Err(error) => {
                        let diagnostic =
                            format!("Could not attach ACP Ask session: {error}");
                        self.status = Some(diagnostic.clone());
                        let _ = self.host.append_message(
                            &gameengine_session_id,
                            ConversationRole::System,
                            diagnostic,
                        );
                        return;
                    }
                };
                if let Err(error) =
                    self.acp
                        .send_prompt(&mut self.host, &acp_session_id, &prompt)
                {
                    let _ = self.acp.close_session(&acp_session_id);
                    let diagnostic = format!("Could not send ACP Ask prompt: {error}");
                    self.status = Some(diagnostic.clone());
                    let _ = self.host.append_message(
                        &gameengine_session_id,
                        ConversationRole::System,
                        diagnostic,
                    );
                    return;
                }
                self.execution_router.sync_registry(self.acp.registry());
                self.acp_question = Some(AcpQuestionState {
                    acp_session_id,
                    gameengine_session_id,
                    answer: String::new(),
                    started_at: std::time::Instant::now(),
                });
                self.status = Some("Waiting for agent…".to_owned());
            }
            AcpStartupTarget::Build {
                gameengine_session_id,
                run_id,
                prompt,
                workspace,
            } => {
                let run_is_current = self.active_run_id.as_deref() == Some(run_id.as_str())
                    && self.host.run(&run_id).is_ok_and(|run| {
                        !matches!(
                            run.state,
                            AgentRunState::Completed
                                | AgentRunState::Failed
                                | AgentRunState::Cancelled
                        )
                    });
                if !run_is_current {
                    let mut session = started.session;
                    let _ = session.cancel();
                    let _ = session.close();
                    return;
                }
                let acp_session_id = match self.acp.attach_started_run_session(
                    &mut self.host,
                    &startup.agent_id,
                    started.runtime,
                    started.session,
                    &gameengine_session_id,
                    &run_id,
                ) {
                    Ok(session_id) => session_id,
                    Err(error) => {
                        self.fail_run(
                            &run_id,
                            format!("Could not attach ACP Build session: {error}"),
                        );
                        return;
                    }
                };
                let runtime_identity = match self.acp.runtime_identity(&acp_session_id) {
                    Ok(identity) => identity,
                    Err(error) => {
                        let _ = self.acp.close_session(&acp_session_id);
                        let message =
                            format!("Could not read negotiated ACP runtime identity: {error}");
                        self.fail_run(&run_id, message.clone());
                        if self.benchmark_child_active() {
                            self.write_benchmark_child_failure(
                                BenchmarkRunFailureKind::Harness,
                                message,
                            );
                        }
                        return;
                    }
                };
                if let Err(error) =
                    self.validate_benchmark_acp_runtime_identity(&runtime_identity)
                {
                    let _ = self.acp.close_session(&acp_session_id);
                    let message = format!("ACP benchmark runtime mismatch: {error}");
                    self.fail_run(&run_id, message.clone());
                    if self.benchmark_child_active() {
                        self.write_benchmark_child_failure(
                            BenchmarkRunFailureKind::Harness,
                            message,
                        );
                    }
                    return;
                }
                if let Err(error) =
                    self.acp
                        .send_prompt(&mut self.host, &acp_session_id, &prompt)
                {
                    let _ = self.acp.close_session(&acp_session_id);
                    self.fail_run(
                        &run_id,
                        format!("Could not send ACP Build prompt: {error}"),
                    );
                    return;
                }
                self.execution_router.sync_registry(self.acp.registry());
                self.code_workspace = Some(workspace);
                self.active_acp_run_session = Some(acp_session_id);
                if let Err(error) = self.host.transition_run(
                    &run_id,
                    AgentRunState::Executing,
                    "ACP external agent runtime started in the isolated code workspace.",
                ) {
                    self.status = Some(error.to_string());
                } else {
                    self.status = Some("Waiting for agent…".to_owned());
                }
            }
        },
    }
    context.request_repaint();
}

